// bg.png embedded as a base64 data URI, loaded as a plain global (same pattern as
// prompts.js) rather than referenced as a separate file:// image src - drawing a
// file://-loaded image onto a canvas taints it in Chromium (no CORS headers on a
// bare local file), which silently breaks canvas.toDataURL()/getImageData() for
// ANY read-back, exactly what applyBackgroundOverlay in index.html needs to do.
// An inline data: URI has no such restriction, so this works whether index.html
// is opened directly (file://) or served over http.
window.STUDIO_FINISH_BG_OVERLAY_DATA_URL = 'data:image/png;base64,';
